package adminServer.mvp.audit;
import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import adminServer.mvp.server.*; import adminServer.mvp.user.User;
@Service public class AuditService {private final AuditLogRepository logs;private final ManagedServerRepository servers;public AuditService(AuditLogRepository l,ManagedServerRepository s){logs=l;servers=s;}@Transactional public void record(User u,String action,UUID serverId,String ip,String details){if(ip==null){var attrs=org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();if(attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servlet)ip=servlet.getRequest().getRemoteAddr();}logs.save(new AuditLog(u,action,serverId==null?null:servers.findById(serverId).orElse(null),ip,details));}@Transactional(readOnly=true)public List<AuditLog> list(){return logs.findTop200ByOrderByCreatedAtDesc();}}
